-- Transport info for the 50 new cities (correct schema)
-- Columns: city_id, public_transport_overview, metro_info, bus_info, ticket_options,
--          family_pass_info, ride_hailing_apps, car_rental_daily_cost, parking_notes, airport_transfer_options

INSERT INTO transport_info (city_id, public_transport_overview, metro_info, bus_info, ticket_options, family_pass_info, ride_hailing_apps, car_rental_daily_cost, parking_notes, airport_transfer_options) VALUES

((SELECT id FROM cities WHERE name='Chiang Mai'), 'Chiang Mai relies on songthaews (shared red pickup trucks) and Grab. The city is spread out so having a plan matters.', 'No metro. Songthaews act as an informal bus network running routes around the old city moat for 20-40 THB.', 'No formal bus network. Songthaew trucks cover all major routes; negotiate for off-route destinations.', 'Shared songthaew 20-40 THB; chartered tuk-tuk 100-200 THB; Grab from ~80 THB.', 'Children under 3 free on songthaews. Charter a full songthaew for the day (800-1,200 THB) for flexibility.', ARRAY['Grab','Bolt'], '400-800 THB/day scooter; 1,200-2,000 THB/day car with driver.', 'Parking easy and free outside city centre. Old city moat area has limited paid parking near the gates.', '[{"method":"Grab car","cost":"200-350 THB","duration":"30 min"},{"method":"Airport taxi","cost":"150-200 THB","duration":"30 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Hanoi'), 'Hanoi is best navigated via Grab. The city bus network is cheap but complex for visitors. Traffic is chaotic — motorbikes dominate.', 'Hanoi Metro Line 2A runs Cat Linh to Ha Dong but limited tourist relevance.', 'Extensive bus network (VND 9,000 per trip) but routes are in Vietnamese only.', 'Grab bike 20,000-50,000 VND; Grab car 80,000-150,000 VND; city bus 9,000 VND; metered taxi 12,000-15,000 VND/km.', 'Children under 6 free on city buses. Grab family car option seats up to 5.', ARRAY['Grab','Be','Gojek'], '600,000-1,200,000 VND/day car with driver recommended over self-drive.', 'Old Quarter parking extremely limited. Most hotels arrange motorbike parking for guests.', '[{"method":"Grab car","cost":"250,000-400,000 VND","duration":"40-50 min"},{"method":"Taxi metered","cost":"200,000-350,000 VND","duration":"40-50 min"},{"method":"City bus 86","cost":"9,000 VND","duration":"60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Ho Chi Minh City'), 'HCMC is best navigated via Grab. Metro Line 1 (Ben Thanh to Suoi Tien) opened late 2024. Traffic is intense during peak hours.', 'Metro Line 1 opened December 2024 — 19.7km, 14 stations. Single ticket 6,000-20,000 VND. Day pass 40,000 VND.', 'Regular buses cover the city (5,000-6,000 VND) but crowded and slow in traffic.', 'Metro single 6,000-20,000 VND; Grab bike 15,000-50,000 VND; Grab car 60,000-150,000 VND.', 'Children under 1m tall ride metro free. Grab GrabFamily seats up to 6 passengers.', ARRAY['Grab','Be','Gojek'], '800,000-1,500,000 VND/day. Self-drive not recommended due to traffic complexity.', 'District 1 parking is expensive and scarce. Use Grab to avoid parking entirely.', '[{"method":"Grab car","cost":"200,000-400,000 VND","duration":"35-60 min"},{"method":"Taxi","cost":"250,000-450,000 VND","duration":"35-60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Taipei'), 'Taipei MRT is one of Asia''s best metro systems — punctual, clean, covers all major tourist destinations. EasyCard works on metro, buses, and YouBike.', 'MRT has 6 lines, 131 stations. Trains every 3-6 minutes peak. Airport MRT connects Taoyuan to city in 35 min (160 TWD).', 'Extensive bus network with stops in English. Taipei Pass covers unlimited MRT and bus for 1/2/3 days.', 'MRT single 20-65 TWD; EasyCard 20% discount; day pass 150 TWD unlimited; Airport MRT 160 TWD.', 'Children under 115cm ride MRT free. EasyCard kids discounts on buses.', ARRAY['Uber','LINE Taxi'], '1,800-3,500 TWD/day. International licence required. Taiwan is right-hand traffic.', 'Parking meters 30-60 TWD/hour in central Taipei. Underground lots at major MRT stations.', '[{"method":"Airport MRT direct","cost":"160 TWD","duration":"35 min"},{"method":"Bus 1819","cost":"125 TWD","duration":"60 min"},{"method":"Taxi","cost":"1,200-1,600 TWD","duration":"40-60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Phuket'), 'Phuket has no reliable public transport. Grab is the safest option. Renting a scooter (200-300 THB/day) is the most practical for independent exploration.', 'No metro. Smart Bus operates on airport-Patong corridor but infrequent.', 'Phuket Smart Bus runs Phuket Town to Rawai via all main beaches (170 THB all-day). Useful for beach-hopping but infrequent.', 'Grab car 200-600 THB; scooter rental 200-300 THB/day; Smart Bus 170 THB all-day.', 'Car rental with driver 1,500-2,500 THB/day for families. Children under 5 free in taxis and Grab.', ARRAY['Grab'], '600-1,200 THB/day scooter; 1,800-3,000 THB/day car.', 'Beach areas have ample free parking. Patong centre has paid lots (20-40 THB/hour).', '[{"method":"Grab car","cost":"400-700 THB","duration":"30-50 min"},{"method":"Airport taxi metered","cost":"500-800 THB","duration":"30-50 min"},{"method":"Smart Bus","cost":"170 THB","duration":"60-90 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Penang'), 'Penang Georgetown is best explored by foot, bicycle, or Grab. The free CAT bus loops inner Georgetown every 15 minutes.', 'No metro. Rapid Penang buses cover the whole island but are slow.', 'Rapid Penang buses RM1.50-4. The free CAT (Central Area Transit) bus covers Georgetown old town every 15 min — excellent for tourists.', 'Rapid Penang bus RM1.50-4; Grab car RM8-25; bicycle rental RM15-30/day.', 'Children under 7 ride Rapid Penang free. Georgetown is very walkable and family-friendly.', ARRAY['Grab','MyCar'], 'RM80-150/day. Penang Bridge toll applies if crossing to mainland.', 'Georgetown has plenty of street parking (RM0.80-2/hour). Lots near Komtar and Gurney Plaza.', '[{"method":"Grab car","cost":"RM25-50","duration":"20-30 min"},{"method":"Rapid Penang bus","cost":"RM4","duration":"45-60 min"},{"method":"Taxi metered","cost":"RM30-50","duration":"20-30 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Colombo'), 'Colombo transport is dominated by three-wheelers and ride-hailing. PickMe is the local app; Uber also works. Commuter rail connects outer suburbs.', 'No metro. Colombo light rail is under construction but not operational.', 'CTB buses are very cheap (LKR 15-100) but crowded and often unmarked in English. Private buses are faster but chaotic.', 'PickMe tuk-tuk LKR 100-400; Uber car LKR 300-800; bus LKR 15-100; metered taxi LKR 50-70/km.', 'Children under 5 free in tuk-tuks. PickMe Kids option available.', ARRAY['PickMe','Uber'], 'LKR 4,000-8,000/day. Roads can be rough outside the city.', 'Colombo 1-7 (central districts) have paid parking. Hotels provide secure parking.', '[{"method":"PickMe car","cost":"LKR 2,000-3,500","duration":"30-50 min"},{"method":"Uber","cost":"LKR 2,500-4,000","duration":"30-50 min"},{"method":"Taxi negotiated","cost":"LKR 3,000-5,000","duration":"30-50 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Kathmandu'), 'Kathmandu transport is served by taxis, micro-buses, and Pathao ride-hailing. Traffic and narrow streets make journeys slow.', 'No metro. Safa Tempos (electric three-wheelers) run fixed east-west routes cheaply.', 'Micro-buses run all main routes (NPR 15-30) but packed and routes unclear for visitors.', 'Pathao bike NPR 100-200; taxi negotiated NPR 200-600; Safa Tempo NPR 15-20.', 'Private car with driver NPR 4,000-8,000/day recommended for families. Children under 5 free in taxis.', ARRAY['Pathao','InDrive'], 'NPR 3,500-7,000/day. Self-drive not practical — use a car with driver.', 'Thamel (tourist district) has very limited parking. Durbar Square area parking available 5-10 min walk away.', '[{"method":"Taxi negotiated","cost":"NPR 600-1,000","duration":"20-40 min"},{"method":"Private car with driver","cost":"NPR 1,500-2,500","duration":"20-40 min"},{"method":"Pathao","cost":"NPR 400-700","duration":"20-40 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Queenstown'), 'Queenstown is a compact resort town. Orbus buses serve main routes. Many adventure activities require rental car or organised transport. Uber operates.', 'No metro. Orbus routes connect Queenstown town centre, Frankton, and Arrowtown.', 'Orbus route 1 (Queenstown-Frankton-Remarkables) and route 8 (Arrowtown) cover key tourist areas. NZ$3-8 per ride.', 'Orbus NZ$3-8; Uber/taxi NZ$12-30; rental car NZ$60-120/day.', 'Orbus under 5 free. Child seats in rental cars — book ahead during ski season.', ARRAY['Uber','Zoomy'], 'NZ$60-120/day standard. Ski season rental should be booked weeks in advance.', 'Queenstown town centre paid parking NZ$2-4/hour. Free parking available in outer Frankton.', '[{"method":"Airport taxi/Uber","cost":"NZ$15-25","duration":"10-15 min"},{"method":"Orbus","cost":"NZ$3","duration":"15-20 min"},{"method":"Super Shuttle","cost":"NZ$18-25 per person","duration":"15 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Chengdu'), 'Chengdu Metro is excellent — 13 lines covering Giant Panda Base, Tianfu Square, and Chunxi Road. Didi (Chinese Uber) covers everything else.', 'Metro: 13 lines, trains every 3-5 min peak. Line 3 goes to Giant Panda Breeding Research Base. Pay via QR code (WeChat/Alipay) or Tianfu Tong card.', 'Extensive bus network (¥2 per ride) but signs are in Chinese only. Metro is far easier for visitors.', 'Metro ¥2-6; Didi car ¥15-50; taxi ¥10-40; bus ¥2.', 'Children under 1.2m ride metro free. Didi supports English-language interface.', ARRAY['Didi'], '¥200-400/day. International licence not valid in China — use Didi or hire car with driver.', 'Chengdu has extensive underground parking at malls and hotels (¥5-10/hour).', '[{"method":"Metro Line 10","cost":"¥10","duration":"40 min"},{"method":"Didi","cost":"¥80-150","duration":"30-60 min"},{"method":"Airport taxi","cost":"¥100-180","duration":"30-60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Nairobi'), 'Nairobi transport is best handled via Uber or Bolt for safety. Matatus (minibuses) are cheap but not recommended for tourists. Traffic is very heavy especially on Mombasa Road.', 'No metro. Nairobi Commuter Rail has limited routes. SGR train connects Nairobi to Mombasa.', 'Matatu minibuses cover every route (KES 30-80) but complex and occasionally unsafe. Best avoided for tourists.', 'Uber/Bolt KES 300-800; Bolt often 20% cheaper than Uber; matatu KES 30-80.', 'Uber and Bolt have family car options. Car hire with driver KES 5,000-10,000/day is popular for families.', ARRAY['Uber','Bolt','Little Cab'], 'KES 4,000-8,000/day. Left-hand traffic. International driving permit required.', 'Parking in Nairobi CBD is paid and heavily enforced (KES 300-600/day lots). Hotels provide secure parking.', '[{"method":"Uber/Bolt","cost":"KES 1,500-3,000","duration":"45-90 min (traffic dependent)"},{"method":"Airport taxi","cost":"KES 2,000-4,000","duration":"30-60 min"},{"method":"SGR shuttle","cost":"KES 200","duration":"20 min to Syokimau station"}]'::jsonb),

((SELECT id FROM cities WHERE name='Cairo'), 'Cairo Metro is fast and essential — 3 lines, 86 stations. Uber is the safest surface option. Traffic is severely congested at all times.', 'Metro: 3 lines. Line 2 goes under the Nile. Line 3 to Adly Mansour. Trains every 3-5 min. Women-only cars at front. EGP 5 per ride any distance.', 'CTA buses cover the whole city (EGP 2-5) but extremely crowded. Microbus (shared taxi) is fast and cheap but chaotic.', 'Metro EGP 5; Uber EGP 50-200; CTA bus EGP 2-5; metered taxi EGP 50-150.', 'Children under 110cm ride metro free. Uber supports car seats on request.', ARRAY['Uber','Careem','InDrive'], 'EGP 800-1,500/day. Cairo traffic makes self-driving very stressful; driver hire recommended.', 'Central Cairo parking is chaotic. Underground lots at City Stars and major malls available.', '[{"method":"Uber/Careem","cost":"EGP 400-800","duration":"45-90 min"},{"method":"Airport bus","cost":"EGP 20","duration":"60-90 min"},{"method":"Taxi negotiated","cost":"EGP 300-600","duration":"45-90 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Amman'), 'Amman has no metro. Careem and Uber are the go-to options. Yellow taxis officially use meters but drivers often refuse — use apps. The city is hilly and not walkable between districts.', 'No metro or rail. JETT bus connects Amman to Aqaba and other cities.', 'JETT (Jordan Express Tourist Transport) for intercity. City buses exist but complex for visitors.', 'Careem/Uber JOD 2-8; metered yellow taxi JOD 1.5-5 (if meter used); service taxi shared JOD 0.5-1.', 'Careem has family car option. Renting a car with driver JOD 35-60/day popular for Petra and Dead Sea day trips.', ARRAY['Uber','Careem'], 'JOD 20-40/day. Roads outside Amman are good. Dead Sea drive is straightforward.', '3rd Circle and Rainbow Street parking is street parking (free). Malls have free multi-level lots.', '[{"method":"Careem/Uber","cost":"JOD 12-20","duration":"30-45 min"},{"method":"Airport taxi metered","cost":"JOD 15-25","duration":"30-45 min"},{"method":"JETT airport bus","cost":"JOD 3","duration":"45 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Tel Aviv'), 'Tel Aviv has the new Red Line light rail (2023). Rav-Kav card covers bus and rail. Note: NO public transport on Shabbat (Friday sunset to Saturday night). Cycling via Tel-O-Fun is excellent.', 'Red Line Light Rail opened 2023: runs Petah Tikva through Tel Aviv to Bat Yam, 34 stations. Trains every 5-8 min. ILS 5.50 per ride.', 'Dan and Egged buses cover Tel Aviv and greater area. Bus 405 (Jerusalem) is a key intercity route.', 'Light rail/bus ILS 5.50 single; Rav-Kav monthly ILS 230; Gett taxi ILS 40-100.', 'Children under 5 free on all public transport. Tel-O-Fun bike share ILS 17/day for unlimited 30-min rides.', ARRAY['Gett','Uber','Yango'], 'ILS 200-400/day. Only for travel outside Tel Aviv; city parking is very expensive.', 'Tel Aviv parking is notoriously difficult and expensive. Blue-white kerb = paid (ILS 6-10/hour). Red-white = no parking.', '[{"method":"Sherut shared taxi Route 5","cost":"ILS 25","duration":"40-50 min"},{"method":"Gett/Uber","cost":"ILS 100-180","duration":"30-50 min"},{"method":"Rail to central station then taxi","cost":"ILS 30","duration":"45 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Muscat'), 'Muscat is very spread out. A rental car is strongly recommended. Uber operates. Mwasalat public buses exist but infrequent.', 'No metro. A metro system has been planned for years but is not yet operational.', 'Mwasalat buses (OMR 0.2-0.5) cover main routes but infrequent (every 30-60 min). Not practical for tourism.', 'Uber OMR 1-5; metered taxi OMR 0.2 flag fall + OMR 0.1/km; car rental OMR 15-25/day.', 'Car rental with driver OMR 25-40/day highly recommended for families. Uber child seat available on request.', ARRAY['Uber'], 'OMR 15-25/day for standard car. Roads are excellent. Driving is safe and straightforward.', 'Free parking is abundant throughout Muscat. Mutrah Corniche and Muttrah Souk have large free lots.', '[{"method":"Uber","cost":"OMR 8-15","duration":"40-60 min"},{"method":"Metered taxi","cost":"OMR 8-15","duration":"40-60 min"},{"method":"Car rental self-drive","cost":"OMR 15+/day","duration":"40-60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Doha'), 'Doha Metro (Gold, Red, Green lines) is modern and covers major tourist areas. Karwa is the official taxi. Uber also operates. The metro is air-conditioned — critical in summer heat above 40C.', 'Doha Metro: 3 lines, 37 stations. Gold Line is most useful for tourists (Katara, Lusail). Trains every 5-8 min. Fare QAR 2-8 per journey.', 'Mowasalat buses cover wider areas. Metro covers main sights well.', 'Metro QAR 2-8; Karwa taxi QAR 20-60; Uber QAR 20-60; airport Karwa QAR 50-80.', 'Children under 5 free on metro. Qatar has family facilities at all major malls and attractions.', ARRAY['Uber','Careem'], 'QAR 150-300/day. Roads are excellent and modern. Parking at malls and attractions is free.', 'Free parking is widely available across Doha — malls, museums, and most attractions have large free car parks.', '[{"method":"Metro Gold Line","cost":"QAR 8","duration":"25 min"},{"method":"Karwa taxi","cost":"QAR 60-100","duration":"20-30 min"},{"method":"Uber","cost":"QAR 60-100","duration":"20-30 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Zanzibar'), 'Zanzibar transport is by taxi, dala-dala (shared minibus), and scooter. Stone Town is walkable. Beach clubs require transport.', 'No metro or rail on Zanzibar.', 'Dala-dalas (shared minibuses) run fixed routes across the island for TZS 1,000-3,000. Cheap but packed and slow.', 'Dala-dala TZS 1,000-3,000; private taxi USD 10-25; scooter rental USD 15-20/day; 4WD rental USD 60-100/day.', 'Private taxis recommended for families. Spice tour drivers typically provide door-to-door service.', ARRAY['Bolt'], 'USD 40-60/day for 4WD recommended for northern beaches. Book via hotel for reliability.', 'Stone Town has very limited and narrow streets — most parking is on the outskirts near the market.', '[{"method":"Private taxi","cost":"USD 15-25","duration":"10-20 min"},{"method":"Dala-dala","cost":"TZS 2,000","duration":"30 min"},{"method":"Hotel shuttle","cost":"USD 10-20","duration":"15-20 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Casablanca'), 'Casablanca has a modern tramway (2 lines), cheap petits taxis (metered), and Uber. The tramway is the fastest way to travel the main corridor.', 'No metro. Tramway Line 1 and Line 2 cover 48km. Tickets MAD 4 per ride.', 'CTM buses cover the whole city (MAD 4-8). Petits taxis (red cabs, metered, 3 passengers max) supplement the tram.', 'Tram MAD 4; petit taxi MAD 10-30; grand taxi MAD 30-80; Uber MAD 30-100.', 'Children under 5 free on trams. Petit taxis take maximum 3 passengers — families need a grand taxi.', ARRAY['Uber','InDriver','Careem'], 'MAD 300-600/day. Roads are good. Self-drive feasible outside the city.', 'Casablanca central area metered street parking (MAD 2-4/hour) and underground lots at major malls.', '[{"method":"Uber/Careem","cost":"MAD 100-200","duration":"30-45 min"},{"method":"Grand taxi","cost":"MAD 150-250","duration":"30-45 min"},{"method":"Bus + tram","cost":"MAD 12","duration":"60-75 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Tunis'), 'Tunis has a useful light metro, the TGM suburban rail to Carthage and Sidi Bou Said, and cheap yellow metered taxis. Traffic is manageable by North African standards.', 'Light Metro: 6 lines serving greater Tunis. TGM suburban rail from Marine station north to La Marsa via Carthage and Sidi Bou Said.', 'TRANSTU buses cover the whole city (TND 0.5-1). Metro and TGM are faster alternatives.', 'Metro TND 0.5-1; TGM TND 1-2; yellow taxi metered TND 0.8 flag fall; Bolt taxi available.', 'Children under 6 free on public transport. Bolt taxis support car seats on request.', ARRAY['Bolt','InDriver'], 'TND 60-120/day. Roads in northern Tunisia are good for coastal visits.', 'Tunis city centre parking is on-street metered (TND 0.5-1/hour). Malls have free parking.', '[{"method":"Bolt/taxi","cost":"TND 20-40","duration":"20-30 min"},{"method":"Metro + TGM","cost":"TND 3","duration":"40-50 min"},{"method":"Yellow taxi metered","cost":"TND 25-45","duration":"20-30 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Accra'), 'Accra transport is dominated by Uber and Bolt. Tro-tros (shared minibuses) are ubiquitous and cheap but complex for visitors. Traffic on Spintex Road can be severe.', 'No metro. Bus Rapid Transit (BRT) corridor is planned but not fully operational.', 'Tro-tros cover every route (GHS 1-5) but unmarked for visitors. Metro Mass Transit buses are an alternative (GHS 2-8).', 'Uber/Bolt GHS 20-80; dropping taxis GHS 20-60; tro-tro GHS 1-5; airport taxi GHS 100-200.', 'Bolt and Uber support family cars. Car hire with driver GHS 400-800/day for families is popular.', ARRAY['Uber','Bolt','Yango'], 'GHS 300-600/day. Roads to Cape Coast (3 hours) and Kumasi are good tarmac roads.', 'Osu, Labone, and Airport Residential parking is fairly easy and mainly free on street.', '[{"method":"Uber/Bolt","cost":"GHS 80-150","duration":"30-60 min"},{"method":"Airport taxi","cost":"GHS 100-200","duration":"30-60 min"},{"method":"Yango","cost":"GHS 70-130","duration":"30-60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Havana'), 'Havana has no ride-hailing apps. Classic American car taxis (almendrones) and Coco taxis (yellow egg-shaped 3-wheelers) cover the city. Negotiate all prices before getting in.', 'No metro. Almendrones (1950s American cars) run fixed routes for residents for 10-20 CUP.', 'Metrobus (P1, P2 routes) covers main corridors cheaply but extremely crowded. Tourist transport is exclusively taxis.', 'Classic car tourist taxi CUC 5-20; coco taxi CUC 3-8; almendron shared route CUP 10-20.', 'Private taxis are standard for families. Classic car tours 1-2 hours available for USD 30-50.', ARRAY[]::text[], 'Classic car rental available for half/full days (USD 40-80). Car hire with a Cuban driver is standard.', 'Havana Vieja is pedestrian-friendly — no parking needed. Hotels in Vedado have parking lots.', '[{"method":"Classic car taxi","cost":"CUC 25-40","duration":"30-45 min"},{"method":"Tourist taxi","cost":"CUC 20-35","duration":"30-45 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Lima'), 'Lima transport: Metropolitano BRT (fast north-south) and ride-hailing. InDriver and Uber are safest. Never hail taxis from the street — use apps only for safety.', 'No metro yet. Metro Line 1 operates with limited tourist use. Line 2 under construction.', 'Metropolitano BRT runs north-south (S/2.50 per trip). Combis (minibuses) cover lateral routes (S/1-2).', 'InDriver S/8-20; Uber S/10-25; Metropolitano S/2.50.', 'InDriver and Uber have family car options. Remis (radio taxi) services offer car seats.', ARRAY['Uber','InDriver','Cabify','Beat'], 'S/80-150/day. Only recommended for day trips outside Lima. City driving is stressful.', 'Miraflores and Barranco have paid parking lots (S/5-10/hour). Street parking is metered in tourist districts.', '[{"method":"Uber/InDriver","cost":"S/50-100","duration":"30-60 min"},{"method":"Airport Express Lima bus","cost":"S/30","duration":"50-70 min"},{"method":"Taxi Remis","cost":"S/70-120","duration":"30-60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Bogotá'), 'Bogotá has TransMilenio BRT (fast and frequent) and Uber operating in a legal grey zone. Ciclovías (closed roads for cyclists) run every Sunday — a special experience.', 'No metro yet. Bogotá Metro Line 1 under construction (expected 2028). TransMilenio BRT acts as the metro alternative with 2.4M daily passengers.', 'TransMilenio BRT: 12 trunk lines, 140 stations. Tullave card (COP 50 cheaper per trip). SITP feeder buses cover all areas.', 'TransMilenio COP 2,950 single; Uber COP 8,000-20,000; InDrive COP 7,000-18,000.', 'Children under 6 free on TransMilenio. Uber family and Cabify family options available.', ARRAY['Uber','InDrive','Cabify'], 'COP 80,000-150,000/day. Pico y placa (congestion) restrictions apply. Driver hire recommended in city.', 'La Candelaria and Chapinero parking lots COP 4,000-8,000/hour. Zona Rosa has multi-level lots.', '[{"method":"Uber/Cabify","cost":"COP 50,000-100,000","duration":"60-90 min"},{"method":"TransMilenio + feeder bus","cost":"COP 5,900","duration":"60-80 min"},{"method":"Taxi metered","cost":"COP 60,000-120,000","duration":"60-90 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Medellín'), 'Medellín has Colombia''s only metro — 2 lines, clean, safe, punctual. Metrocable gondolas extend into hillside comunas. All on the same Civica card.', 'Metro: Line A (Niquia-La Estrella) and Line B (San Antonio-San Javier). Metrocable: 3 lines to hillside comunas and Parque Arvi. Trains every 3-8 min. Fare COP 3,200.', 'Metro feeder buses and integrated bus corridors cover outer areas on the same Civica card.', 'Metro/cable COP 3,200 per trip; Civica day pass COP 9,600; Uber COP 8,000-20,000.', 'Children under 1m ride metro free. Metrocable to Parque Arvi is an unmissable family experience.', ARRAY['Uber','InDrive','Cabify'], 'COP 70,000-130,000/day. Only needed for Guatape or Coffee Region day trips.', 'El Poblado and Laureles parking in private lots COP 3,000-6,000/hour.', '[{"method":"Uber/InDrive","cost":"COP 60,000-120,000","duration":"50-80 min"},{"method":"Taxi metered","cost":"COP 50,000-100,000","duration":"50-80 min"},{"method":"Bus + metro","cost":"COP 6,400","duration":"80-100 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Santiago'), 'Santiago Metro is one of Latin America''s best — 7 lines, 136 stations, 3M daily passengers. Bip! card is mandatory for metro and buses. Uber and Cabify operate for surface transport.', 'Metro: 7 lines. Trains every 2-4 min peak hours. Blue and Express trains skip intermediate stations. CLP 800 off-peak / CLP 950 peak on Bip! card.', 'Transantiago buses integrate with metro using the same Bip! card — one transfer free within 90 min.', 'Metro CLP 800-950; Bip! day pass CLP 3,500; Uber CLP 3,000-8,000; Cabify CLP 3,000-8,000.', 'Children under 6 free on metro. Uber/Cabify support child seats on request.', ARRAY['Uber','Cabify','inDriver'], 'CLP 30,000-60,000/day. Only needed for Casablanca wine valley or coastal day trips.', 'Santiago CBD parking lots CLP 1,500-3,000/30 min. Bellavista and Lastarria have free street parking in evenings.', '[{"method":"Centropuerto bus","cost":"CLP 2,900","duration":"45 min"},{"method":"Uber/Cabify","cost":"CLP 12,000-20,000","duration":"30-45 min"},{"method":"Taxi metered","cost":"CLP 18,000-25,000","duration":"30-45 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='São Paulo'), 'Sao Paulo has an extensive Metro (6 lines) and CPTM commuter rail. Uber is essential for anything off-metro. Traffic above ground is notoriously bad.', 'Metro: 6 lines (1-5 and 15 monorail), 93 stations. VT card works on metro, CPTM, and buses. Trains every 2-5 min peak hours.', 'SPTrans buses cover every corner of Sao Paulo (R$5 with bilhete unico). Metro-bus integration available.', 'Metro R$5; Uber R$15-50; 99 (local ride-hail) R$12-45; taxi R$20-60.', 'Children under 1.1m ride metro free. Uber has child seat option in Sao Paulo.', ARRAY['Uber','99','Cabify'], 'R$150-300/day. Only useful for day trips to Serra da Cantareira or Guaruja beach.', 'Sao Paulo centre parking in paid underground lots R$15-40/hour. Vila Madalena metered R$5-10/hour.', '[{"method":"Uber/99","cost":"R$60-120","duration":"40-70 min"},{"method":"Metro + bus","cost":"R$10","duration":"60-80 min"},{"method":"Taxi metered","cost":"R$80-150","duration":"40-70 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Cartagena'), 'Cartagena''s Walled City is best explored entirely on foot. Air-conditioned taxis are essential for Bocagrande and Getsemani. InDriver operates here.', 'No metro or formal rail.', 'No bus network useful for tourists. Chiva (colourful traditional bus) tours are a nightlife experience.', 'Taxi negotiated COP 8,000-20,000; InDriver COP 7,000-15,000; bicycle rental COP 20,000-30,000/day.', 'Taxis accommodate families easily. Negotiate prices upfront — sometimes inflated for tourists with children.', ARRAY['InDriver'], 'COP 150,000-300,000/day. Very useful for Playa Blanca and island day trips.', 'Las Murallas (Walled City) is mostly pedestrian. Hotels in Bocagrande have parking.', '[{"method":"Taxi","cost":"COP 40,000-80,000","duration":"20-30 min"},{"method":"InDriver","cost":"COP 35,000-70,000","duration":"20-30 min"},{"method":"Water taxi from Old City","cost":"COP 80,000-120,000","duration":"20 min by boat"}]'::jsonb),

((SELECT id FROM cities WHERE name='Montevideo'), 'Montevideo has excellent STM buses and a pleasant walkable Rambla (coastal promenade). Uber operates. Taxis are metered and honest.', 'No metro. STM buses are the main public transport — 50+ routes, clean and on time by regional standards.', 'STM bus network: UYU 35 per ride (contactless or Montevideo Card). Routes 64, 21, 103 cover most tourist areas.', 'STM bus UYU 35; Uber UYU 200-500; taxi metered UYU 200-400; Movete bike share UYU 60/day.', 'Children under 6 free on STM buses. Uber child seat available on request.', ARRAY['Uber','DiDi'], 'UYU 1,500-3,000/day. Only useful for Colonia del Sacramento day trip (1.5h drive) or coastal towns.', 'Montevideo Ciudad Vieja and Centro: metered street parking UYU 60-100/hour or free in evenings.', '[{"method":"Uber/DiDi","cost":"UYU 500-1,000","duration":"20-30 min"},{"method":"Bus Cutcsa 700","cost":"UYU 35","duration":"35-50 min"},{"method":"Taxi metered","cost":"UYU 500-900","duration":"20-30 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Chicago'), 'Chicago''s CTA "L" elevated train is iconic and practical — 8 lines, 145 stations, running 24/7 on Red and Blue lines. Ventra app handles all ticketing. The Loop is also very walkable.', 'CTA L: 8 lines. Blue Line runs 24/7 to O''Hare. Red Line runs 24/7 through Loop and North Side. Orange Line to Midway Airport. Trains every 3-12 min. Fare $2.50 (Ventra).', 'CTA buses cover the full city grid. Route 151 (Sheridan) and Route 66 (Chicago Ave) are tourist-useful.', '$2.50 with Ventra card; $2.75 cash; Ventra 3-day unlimited $20; Uber/Lyft $12-25.', 'Children under 7 ride CTA free with a paying adult (up to 3 children per adult). Ventra day passes for older kids.', ARRAY['Uber','Lyft'], '$50-100/day. Parking in Chicago is expensive — avoid driving downtown.', 'Downtown Chicago (Loop): garages $30-50/day. River North metered $4/hour. Lincoln Park street parking competitive.', '[{"method":"Blue Line L (O Hare)","cost":"$5 premium fare","duration":"45 min"},{"method":"Orange Line L (Midway)","cost":"$2.50","duration":"25 min"},{"method":"Uber/Lyft","cost":"$30-50","duration":"25-45 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='New Orleans'), 'New Orleans'' French Quarter is best explored on foot. The historic St. Charles streetcar runs through the Garden District. Lyft and Uber are plentiful.', 'No metro. St. Charles streetcar (Line 12) has run since 1835 — one of the world''s oldest continuously operating streetcars. Canal Street streetcar also runs.', 'RTA buses cover the whole city. Streetcars are the main tourist transport.', '$1.25 streetcar; Jazzy Pass $3 unlimited day; Lyft/Uber $8-25; taxi $3.50 flag fall + $2/mile.', 'Children under 3 free on streetcars. Lyft family car available.', ARRAY['Uber','Lyft'], '$60-100/day. Only useful for plantations on River Road or Gulf Coast day trips. Downtown chaotic during events.', 'French Quarter parking metered ($1.50/hour) or Canal Street lots ($25-40/day). Magazine Street residential parking available.', '[{"method":"Lyft/Uber","cost":"$30-50","duration":"20-30 min"},{"method":"Taxi metered","cost":"$35-55","duration":"20-30 min"},{"method":"Shared shuttle","cost":"$20 per person","duration":"25-35 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Oslo'), 'Oslo''s Ruter integrated transport covers T-bane (metro), trams, buses, and harbour ferries on a single ticket. Oslo is expensive — buy a 24/72-hour pass for significant savings.', 'T-bane: 6 lines, 101 stations. Frognerseteren (Line 1) for Holmenkollen and forest hikes. All lines connect at Majorstuen and Stortinget. Trains every 4-6 min peak hours.', 'Trams cover the city centre — lines 12 and 19 most useful for tourists. Frequent and punctual.', 'Single NOK 42 (app) or NOK 51 (card); 24-hour pass NOK 127; 72-hour pass NOK 220. All modes included.', 'Children 6-15 half price. Under 6 free. Oslo Pass (NOK 595/24h) includes transport and museum entry.', ARRAY['Uber','Bolt','Oslo Taxi'], 'NOK 700-1,400/day. Fjord and countryside day trips from Oslo popular with rental cars.', 'Oslo city centre parking expensive (NOK 60-80/hour in lots). Park and Ride at outer T-bane stations are free.', '[{"method":"Flytoget Airport Express","cost":"NOK 238","duration":"20 min"},{"method":"T-bane Line 2 + bus","cost":"NOK 42","duration":"40 min"},{"method":"SAS Flybussen","cost":"NOK 179","duration":"40 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Tallinn'), 'Tallinn has an integrated tram, bus, and trolleybus network. The Old Town is fully walkable. Tram line 2 from the airport is the best arrival option.', 'No metro. Trams: 4 lines. Tram 2 connects the airport to the city centre in 15 min. Trolleybuses cover outer districts.', 'Buses cover the whole city and outer suburbs. All buses, trams, and trolleybuses use the same Uhiskaart smartcard.', 'Single EUR 1.50 (Uhiskaart) or EUR 2 cash on board; 24-hour pass EUR 4.50; weekly pass EUR 11.', 'Children under 7 travel free. Tallinn Card (EUR 25/24h) includes all public transport and major museum entries.', ARRAY['Bolt','Uber'], 'EUR 40-80/day. Old Town is pedestrian-only. Cars useful for Lahemaa National Park day trips.', 'Old Town is car-free. Parking on surrounding streets EUR 1-3/hour. Ulemiste shopping centre has large free lots.', '[{"method":"Tram 2","cost":"EUR 1.50","duration":"15 min"},{"method":"Bolt/Uber","cost":"EUR 8-15","duration":"10-15 min"},{"method":"Taxi","cost":"EUR 10-18","duration":"10-15 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Riga'), 'Riga has an extensive tram, trolleybus, and bus network. The Old Town (Vecriga) is walkable. e-Ticket system or contactless payment on all vehicles. Bolt taxi is reliable and cheap.', 'No metro. Trams: 11 lines. Tram 1 and 2 connect the airport and central station. Trolleybuses: 11 lines covering outer districts.', 'Buses cover the full metropolitan area. Airport bus 22 runs to central station (EUR 1.15, 30 min).', 'e-talons single EUR 1.15; 24-hour pass EUR 5; 72-hour pass EUR 10; monthly EUR 50.', 'Children under 7 free. Riga Card (EUR 35/24h) includes transport and museum discounts.', ARRAY['Bolt','Uber'], 'EUR 40-80/day. Latvia has good roads for day trips to Jurmala or Sigulda.', 'Riga Old Town: mostly car-free. Central area parking meters EUR 1-3/hour. ParkRiga app for cashless parking.', '[{"method":"Bus 22 to centre","cost":"EUR 1.15","duration":"30 min"},{"method":"Bolt","cost":"EUR 8-15","duration":"15-20 min"},{"method":"Taxi","cost":"EUR 12-20","duration":"15-20 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Vilnius'), 'Vilnius Old Town is entirely walkable (UNESCO heritage site). City buses and trolleybuses are cheap and cover the wider city. Bolt scooters and taxis are popular.', 'No metro. Trolleybuses: 22 lines. Bus network: extensive, covers all suburbs.', 'Bus and trolleybus system uses m.Ticket app (EUR 1 per trip, 24-hour pass EUR 3). Route 1 bus is useful (train station to Old Town).', 'm.Ticket EUR 1 single; 24-hour pass EUR 3; weekly pass EUR 10; Bolt taxi EUR 4-12.', 'Children under 7 free. Bolt family car option available.', ARRAY['Bolt','Uber','CityBee'], 'EUR 40-80/day. Good for day trips to Trakai Castle (28km) and Aukstaitija National Park.', 'Old Town parking is limited and expensive (EUR 2-4/hour). Multi-storey lots at Akropolis and Europa malls free with purchase.', '[{"method":"Bolt","cost":"EUR 8-15","duration":"15-20 min"},{"method":"Bus 1 from Vilnius station","cost":"EUR 1","duration":"20-25 min"},{"method":"Taxi","cost":"EUR 10-18","duration":"15-20 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Valletta'), 'Valletta is tiny — the entire walled city is a 15-minute walk end to end. Malta Public Transport buses connect to the rest of the island from Valletta terminal.', 'No metro. Valletta itself is almost entirely car-free within the walls.', 'Malta Public Transport buses radiate from Valletta terminal to all parts of the island. Route X2 to airport, Route 202 to Mdina.', 'Single EUR 2 (24-hour pass EUR 3, 7-day EUR 21); Ferry to Gozo EUR 4.65 return; Bolt taxi EUR 8-20.', 'Children 5-11 half price. Under 5 free. Malta Transport App for journey planning.', ARRAY['Bolt'], 'EUR 30-60/day. Essential for beaches on the north coast and day trips around the island.', 'Valletta city walls are car-free. Park at Floriana Park and Ride (free with bus ticket) then walk in.', '[{"method":"Bus X2","cost":"EUR 2","duration":"20 min"},{"method":"Bolt taxi","cost":"EUR 15-25","duration":"15 min"},{"method":"Taxi metered","cost":"EUR 15-25","duration":"15 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Ljubljana'), 'Ljubljana''s car-free city centre makes it one of Europe''s most walkable capitals. Kavalir electric buggies provide free transport within the pedestrian zone. BicikeLJ bike sharing has 36 stations.', 'No metro. Ljubljana has a small but useful LPP bus network covering the wider city.', 'LPP buses use Urbana contactless card (EUR 0.80/ride or EUR 3.50/day). Route 2 and 6 connect the bus/train station to Metelkova.', 'LPP bus EUR 0.80/ride; Urbana day pass EUR 3.50; BicikeLJ bike share EUR 3/day; Bolt taxi EUR 5-12.', 'Children under 7 free on LPP buses. The pedestrian centre is entirely stroller-friendly.', ARRAY['Bolt','Uber'], 'EUR 30-60/day. Only useful for Lake Bled (55km), Postojna Cave, or Predjama Castle day trips.', 'City centre is car-free. Central parking garage (Kongresni trg) at EUR 2/hour. Tivoli Park area has free street parking.', '[{"method":"Bolt/Uber","cost":"EUR 15-25","duration":"20-30 min"},{"method":"GoOpti airport shuttle","cost":"EUR 9-15","duration":"20-25 min"},{"method":"Taxi","cost":"EUR 20-30","duration":"20-25 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Sarajevo'), 'Sarajevo has a historic tram network (Line 1 since 1885) and trolleybuses. The city is compact and walkable between Bascarsija and the Cathedral area.', 'No metro. Tram Line 1 runs from Bascarsija to Ilidza (45 min full route) — the most useful for tourists.', 'Trolleybuses serve outer western suburbs. City buses cover outlying areas.', 'Tram single BAM 1.80 (from driver) or BAM 1.60 (pre-bought from kiosk); taxi metered BAM 1.50/km; Bolt taxi available.', 'Children under 6 free on trams. Taxis are cheap and drivers are generally honest.', ARRAY['Bolt','Yandex Go'], 'BAM 40-80/day. Good for day trips to Mostar (2.5h) or Konjic.', 'Bascarsija area is semi-pedestrian — limited parking. Austro-Hungarian quarter has more street parking.', '[{"method":"Bolt","cost":"BAM 20-35","duration":"25-35 min"},{"method":"Taxi metered","cost":"BAM 20-35","duration":"25-35 min"},{"method":"Airport bus Centrotrans","cost":"BAM 5","duration":"30 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Tbilisi'), 'Tbilisi Metro (2 lines, 22 stations) covers central areas efficiently. Bolt taxi is extremely cheap and reliable. The cable car to Narikala Fortress is a tourist highlight.', 'Metro: Line 1 (Akhmeteli-Varketili) and Line 2 (Saburtalo spur). Metromoney card required (GEL 2 card fee). Trains every 3-8 min.', 'Marshrutka minibuses cover most routes (GEL 0.50-1). City buses use the same Metromoney card as metro (GEL 1/trip).', 'Metro GEL 1/trip; bus GEL 1/trip; Bolt taxi GEL 3-12; yellow cab negotiated GEL 5-15.', 'Children under 6 free on metro. Bolt is the most reliable and transparent for families.', ARRAY['Bolt','Yandex Go'], 'GEL 80-150/day. Roads to Kazbegi (3h) and Kakheti wine region (1.5h) are well-maintained.', 'Rustaveli Avenue and Old Town: very limited parking. Multi-storey lots at Galleria Tbilisi mall.', '[{"method":"Metro + taxi","cost":"GEL 25-40","duration":"35-50 min"},{"method":"Bolt","cost":"GEL 30-50","duration":"35-50 min"},{"method":"Fixed taxi from airport","cost":"GEL 35-45","duration":"30-40 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Santorini'), 'Santorini is a small island best navigated by KTEL bus between villages or rented ATV/scooter. The famous Fira-to-Oia walk (10km, caldera-edge) is the best way to experience the island.', 'No metro. Cable car from Fira port to Fira town (EUR 6 single).', 'KTEL buses depart from Fira central terminal to Oia (30 min, EUR 1.80), Perissa beach, Akrotiri. Roughly every 30 min in summer.', 'KTEL bus EUR 1.80-2.50; ATV rental EUR 25-40/day; taxi EUR 10-20 per ride; cable car EUR 6.', 'ATVs and scooters not suitable for young children. Taxis limited in number — book via your hotel. Private transfers from port USD 15-25.', ARRAY[]::text[], 'EUR 25-40/day ATV or scooter; EUR 80-150/day car. Roads are narrow and winding.', 'Fira and Oia have extremely limited parking. ATVs and scooters are far more practical than cars.', '[{"method":"Bus port shuttle","cost":"EUR 2","duration":"20 min"},{"method":"Private transfer","cost":"EUR 15-25","duration":"15 min"},{"method":"Cable car + walk","cost":"EUR 6","duration":"20 min walk"}]'::jsonb),

((SELECT id FROM cities WHERE name='Bruges'), 'Bruges medieval city centre is entirely car-free and best explored on foot or bicycle. The Markt and Burg squares are at the heart of a compact 30-minute walkable city.', 'No metro. Bruges station is 15 min walk from the Markt.', 'De Lijn city buses depart from the station and ''t Zand square to the Markt area. Bruges city bus EUR 1.80.', 'De Lijn bus EUR 1.80 (app) or EUR 3 cash; bicycle rental EUR 4/hour or EUR 12/day; horse carriage tour EUR 50/carriage.', 'Cycling with children — many rentals offer child seats and cargo bikes. Most attractions are within 10 min walk.', ARRAY['Taxi Bruges'], 'EUR 30-60/day. Useful for day trip to the coast or Ghent.', 'Cars are strongly discouraged in central Bruges. Use P+R lots on the ring road (free with bus ticket) and take the free bus.', '[{"method":"Train from Brussels or Ghent","cost":"EUR 15-20","duration":"60 min from Brussels"},{"method":"Taxi from station","cost":"EUR 10-15","duration":"10 min"},{"method":"Walk from station","cost":"Free","duration":"15 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Florence'), 'Florence''s historic centre (ZTL zone) is largely closed to private cars. The city is almost entirely walkable — Duomo to Uffizi is a 5 min walk. ATAF buses serve wider Florence.', 'No metro. ATAF buses are the main public transport. Tram Line T1 connects Scandicci to Santa Maria Novella station.', 'ATAF buses: single EUR 1.50 (90 min), day pass EUR 5. Vespucci Express bus links airport to Santa Maria Novella station.', 'ATAF bus EUR 1.50; day pass EUR 5; Uber/Taxify EUR 8-20; taxi metered EUR 3.30 + EUR 0.90/km.', 'Florence historic centre is stroller-friendly on major routes but cobblestones challenge small wheels in side streets.', ARRAY['Uber','itTaxi'], 'EUR 40-80/day. ZTL fines EUR 100+ — never drive in the centre. Cars useful for Chianti, Siena, Cinque Terre.', 'ZTL covers all of historic Florence. Park at Piazzale Michelangelo (EUR 2/hour) or Parterre garage and walk or take a bus.', '[{"method":"ATAF bus Vespucci Express","cost":"EUR 6","duration":"20 min"},{"method":"Taxi metered","cost":"EUR 20-30","duration":"20 min"},{"method":"Uber","cost":"EUR 18-28","duration":"20 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Naples'), 'Naples has Metro Lines 1 and 6, historic Funicolare lines to Vomero, and the Circumvesuviana commuter rail to Pompeii, Herculaneum, and Sorrento. Unico Campania pass covers all modes.', 'Metro Line 1 (Piscinola to Garibaldi): art-station metro with world-class installations at Toledo and Universita stops. Line 2 (Gianturco to Pozzuoli). Trains every 4-8 min.', 'ANM city buses: single EUR 1.60; day pass EUR 4.50. Circumvesuviana trains for Pompeii (45 min, EUR 3.20).', 'Metro single EUR 1.60; Unico Napoli day pass EUR 4.50; Circumvesuviana to Pompeii EUR 3.20; Funicolare EUR 1.60.', 'Children under 6 free on all ANM transport. Pompeii is excellent for older children (8+).', ARRAY['Uber','itTaxi','Free Now'], 'EUR 40-80/day. Self-drive in Naples extremely stressful. Car only for Amalfi Coast or Caserta.', 'Naples historic centre: no car access. Park at Piazza Garibaldi and use metro. Waterfront (Mergellina) has paid lots EUR 1-2/hour.', '[{"method":"Alibus airport bus","cost":"EUR 5","duration":"20 min to central station"},{"method":"Taxi fixed rate","cost":"EUR 23 to centre","duration":"20-30 min"},{"method":"Metro Line 1 from Garibaldi","cost":"EUR 1.60","duration":"10 min to centre"}]'::jsonb),

((SELECT id FROM cities WHERE name='Salzburg'), 'Salzburg is compact and walkable — the Altstadt (Old Town) is UNESCO listed and largely pedestrian. Salzburg Card covers all public transport plus free museum entry.', 'No metro. Stadtbahn (regional S-Bahn) serves surrounding towns. Trolleybuses and motor buses cover the city.', 'Obus trolleybuses are the main city transport. Lines 1, 2, 3, 6 connect the Altstadt to outlying areas. S-Bahn to Hallein (17 min) and Freilassing.', 'Single EUR 2.10; Tageskarte (day pass) EUR 5.70; Salzburg Card 24h EUR 27 / 48h EUR 35 / 72h EUR 42 (includes everything).', 'Salzburg Card includes all buses plus Festung funicular and museum entries — exceptional family value. Under 6 free on all transport.', ARRAY['Uber','Taxi 8111'], 'EUR 50-100/day. Excellent for Berchtesgaden (40 min), Wolfgangsee lake, and Eagle''s Nest.', 'Old Town is pedestrian — no driving. Park and Ride at Alpenstrasse (free bus shuttle to centre). City centre garages EUR 2-3/hour.', '[{"method":"Obus 2 from Hauptbahnhof","cost":"EUR 2.10","duration":"15 min"},{"method":"Taxi","cost":"EUR 20-30","duration":"15 min"},{"method":"Salzburg Airport shuttle bus","cost":"EUR 3","duration":"15 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Ghent'), 'Ghent is extremely cycling-friendly and has an excellent De Lijn tram and bus network. The car-free inner city is a 20-minute walk from the station. Blue-Bike rental at the station is ideal.', 'No metro. Trams: Lines 1 and 2 are the most useful for tourists (Ghent-Sint-Pieters to Korenmarkt). Predmetro tunnel section under the city centre.', 'De Lijn buses radiate from all tram termini. All use the same payment (contactless or De Lijn app).', 'De Lijn single EUR 1.80 (app) or EUR 3 cash; day pass EUR 7; Blue-Bike EUR 3.50/day.', 'Ghent is very family-friendly with excellent cycling infrastructure including family cargo bike rentals.', ARRAY['Uber','Bolt'], 'EUR 30-70/day. Only useful for Bruges (30 min) or Antwerp (55 min) day trips.', 'Ghent''s inner city is car-free. Park at Parking Tolhuis or Parking Ramen (EUR 4-6/day) and tram/walk to centre.', '[{"method":"Tram 1 or 2 from Ghent station","cost":"EUR 1.80","duration":"10 min"},{"method":"Bolt","cost":"EUR 8-15","duration":"10-15 min"},{"method":"Train to Ghent-Dampoort then walk","cost":"EUR 3-5","duration":"20 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Bordeaux'), 'Bordeaux''s TBM tram network is modern, frequent, and covers the whole city. V3 bike sharing has 1,500 bikes at 170 stations. Bordeaux is flat and extremely cycling-friendly.', 'No metro. Trams: 4 lines (A, B, C, D). Line C connects airport to central Bordeaux (Quinconces) in 40 min. Trams run every 3-5 min.', 'TBM buses serve areas not covered by tram. Lianes rapid bus lines supplement the tram network.', 'TBM single EUR 1.70 (1 hour any mode); 24-hour pass EUR 4.70; V3 bike first 30 min free (EUR 1.80/day subscription).', 'V3 bike share ideal for flat Bordeaux. TBM family day pass EUR 9.40.', ARRAY['Uber','Bolt'], 'EUR 40-80/day. Great for Saint-Emilion (50 min), Arcachon Bay (1h), and Medoc wine chateaux.', 'Bordeaux city centre: metered parking EUR 1.50-3/hour. Place de la Victoire and Meriadeck garages at EUR 1.50/hour.', '[{"method":"Tram C airport line","cost":"EUR 1.70","duration":"40 min"},{"method":"Uber","cost":"EUR 25-40","duration":"25-35 min"},{"method":"Taxi","cost":"EUR 30-45","duration":"25-35 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Lyon'), 'Lyon has an excellent TCL network — 4 metro lines, 7 tram lines, 2 funiculars (Fourviere, Saint-Just), and buses, all on one ticket. Velo''v bike share covers the flat Presqu''ile.', 'Metro: Lines A, B, C, D. Funicular F1 to Fourviere Basilica — avoid the steep climb. Trains every 2-6 min peak. Rhonexpress tram goes to airport.', 'Trams: 7 lines serving suburbs. T2 goes to the stadium. Buses serve outer arrondissements.', 'TCL single EUR 1.90; 24-hour pass EUR 6; 3-day EUR 13.60; Rhonexpress airport tram EUR 16.90.', 'Under 6 free on TCL. Lyon City Card (EUR 27/24h) includes all transport and museums.', ARRAY['Uber','Bolt','Free Now'], 'EUR 35-75/day. Excellent for Beaujolais wine region (40 min) and Annecy (1.5h).', 'Presqu''ile and Vieux Lyon: expensive and limited parking (EUR 3-5/hour). Use Park and Ride at outer metro lines (free with ticket).', '[{"method":"Rhonexpress tram","cost":"EUR 16.90","duration":"30 min"},{"method":"Uber/Bolt","cost":"EUR 40-60","duration":"30-45 min"},{"method":"Taxi metered","cost":"EUR 45-65","duration":"30-45 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Malaga'), 'Malaga has a 2-line metro connecting the airport to the city centre. EMT city buses are comprehensive. RENFE Cercanias commuter trains serve the Costa del Sol. The historic centre is very walkable.', 'Metro: Line 1 (Andalucia Tech to Malaga Centro-Alameda). Airport connection: take Line 1 to Malaga Centro (12 min, EUR 1.35).', 'EMT city buses: 40+ lines covering all neighbourhoods. Route 19 (beach), Route 4 (Paseo del Parque). Single EUR 1.35; 10-trip card EUR 8.30.', 'Metro EUR 1.35; EMT bus EUR 1.35; 10-trip card EUR 8.30; Cercanias to Fuengirola EUR 3.80; Uber EUR 8-20.', 'Children under 6 free on metro and buses. Beach buses and Cercanias great for family beach days.', ARRAY['Uber','Bolt','Cabify'], 'EUR 30-60/day. Costa del Sol coastal towns easily accessed. Ronda day trip (1.5h) worth it.', 'Malaga centre: parking in underground lots at Plaza de la Marina and Carrefour (EUR 1-2/hour). Free parking on Av. de Andalucia evenings.', '[{"method":"Metro Line 1","cost":"EUR 1.35","duration":"12 min"},{"method":"Bus 75 Expres Aeropuerto","cost":"EUR 3","duration":"20-25 min"},{"method":"Uber/Bolt","cost":"EUR 12-20","duration":"15-20 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Granada'), 'Granada''s historic centre is best explored on foot. The free Albaiicin minibuses (C30, C31, C32) navigate the steep narrow streets. EMT city buses cover the wider city.', 'No metro. LAC urban buses and free Albaicin minibuses are the main public transport.', 'LAC buses: single EUR 1.40; bonobuses 10-trip card EUR 7.90; Albaicin minibuses C30-C34 are free and essential for the steep hill. Route SN1 serves the Alhambra from Gran Via.', 'LAC bus EUR 1.40; 10-trip bonobuses EUR 7.90; Albaicin minibuses free; taxi metered EUR 1.06/km.', 'Albaicin minibuses perfect for families with young children to navigate the steep Moorish quarter. Alhambra has accessible paths.', ARRAY['Uber','Bolt','Cabify'], 'EUR 30-60/day. Only useful for Sierra Nevada (45 min) or Alpujarras villages.', 'Granada centre: very limited parking. Triunfo underground garage (EUR 1.80/hour) is the most central. Free street parking in Zaidin neighbourhood.', '[{"method":"Uber/Bolt from Malaga airport","cost":"EUR 20-30","duration":"90 min from Malaga"},{"method":"ALSA bus from Malaga","cost":"EUR 12-18","duration":"100 min"},{"method":"Taxi within city","cost":"EUR 8-15","duration":"10-20 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Hoi An'), 'Hoi An Ancient Town is a UNESCO World Heritage site almost entirely car-free. Bicycles are the perfect mode of transport — flat terrain, rice paddy roads, and beach access.', 'No metro or rail. The nearest train station is Da Nang (30km away).', 'No formal bus network within Hoi An. Da Nang to Hoi An by local bus VND 30,000, 1 hour.', 'Bicycle rental VND 40,000-60,000/day; motorbike rental VND 100,000-150,000/day; Grab from Da Nang VND 200,000-300,000.', 'Bicycles with child seats and family cargo bikes available from most guesthouses. Flat terrain means all ages can cycle.', ARRAY['Grab'], 'Bicycle is the primary vehicle. Motorbikes from VND 100,000/day. Da Nang to Hoi An by car VND 300,000-500,000.', 'Hoi An old town is pedestrian only from 7am onwards. Park bicycles at designated racks. Hotels have parking for motorbikes.', '[{"method":"Grab from Da Nang airport","cost":"VND 250,000-400,000","duration":"40-50 min"},{"method":"Taxi from Da Nang","cost":"VND 300,000-500,000","duration":"40-50 min"},{"method":"Bus from Da Nang","cost":"VND 30,000","duration":"60 min"}]'::jsonb),

((SELECT id FROM cities WHERE name='Chiang Rai'), 'Chiang Rai is a small city where tuk-tuks, songthaews (red truck taxis), Grab, and rental scooters cover all transport needs. White Temple, Blue Temple, and Black House require organised transport.', 'No metro. Chiang Rai is a small city with no rail connection.', 'No formal bus network. Songthaews (red pickup trucks) cover main routes within the city for THB 30-50.', 'Songthaew shared THB 30-50; Grab car THB 100-250; tuk-tuk THB 100-200; scooter rental THB 250-400/day.', 'Private songthaew or tuk-tuk charter for a temple circuit (THB 400-700 half day) ideal for families.', ARRAY['Grab'], 'THB 250-400/day scooter; THB 1,000-1,500/day car. Roads to Golden Triangle and Doi Tung are well-maintained.', 'Chiang Rai city centre: free parking near the Night Bazaar and Clock Tower roundabout. Temples have free parking lots.', '[{"method":"Grab/taxi from airport","cost":"THB 150-250","duration":"15-20 min"},{"method":"Tuk-tuk from airport","cost":"THB 100-200","duration":"20 min"},{"method":"Songthaew","cost":"THB 50-80","duration":"25-30 min"}]'::jsonb)

ON CONFLICT DO NOTHING;
